window.globiquest.moveScopeNearGlobe=()=>{const T=AFRAME.THREE,globe=document.getElementById('mapRoot')?.object3D;if(!globe)return;const object=telescopeRoot.object3D,center=scopeView.object3D.getWorldPosition(new T.Vector3()),toward=globe.getWorldPosition(new T.Vector3()).sub(center),distance=toward.length();if(distance<.35)return;const delta=toward.normalize().multiplyScalar(Math.min(.25,distance-.35)),dragger=scopeView.components?.['xr-nav-drag'];if(dragger){dragger.end(true);dragger.pose=null}for(const [key,r] of window.globiquest.objectSizer?.positions||[])if(r.object===object||r.object===scopeView.object3D)window.globiquest.objectSizer.positions.delete(key);object.position.copy(object.parent.worldToLocal(object.getWorldPosition(new T.Vector3()).add(delta)));telescopeRoot.dataset.userPlaced='true';object.updateWorldMatrix(true,true);window.globiquest.presentCelestial?.();return delta.length()};
