function toggleScope(force){const next=typeof force==='boolean'?force:!scopeActive;if(next&&window.globiquest.parachutes?.open)return;if(next){if(featureOpen)closeAdventure();window.globiquest.setWorkspace?.('home');adventure.award(regions[state.region],'visits',String(state.place))}scopeActive=next;scopeBringButton.hidden=!next;window.globiquest.renderXRNav?.(document.getElementById('nav'));scopeView.setAttribute('visible',next);constellations.setAttribute('visible',next);const component=scopeComponent();if(component){component.active=next;component.last=-1000}if(next){renderScopeControls();scopeView.querySelectorAll('[data-feature-interactive]').forEach(el=>{el.classList.add('interactive');el.removeAttribute('data-feature-interactive')});constellations.querySelectorAll('[data-feature-interactive]').forEach(el=>{el.classList.add('interactive');el.removeAttribute('data-feature-interactive')});window.globiquest.presentCelestial?.();notify('Celestial explorer · + / − to zoom. Select a glowing star to visit a region.')}else{window.globiquest.scopeCountriesOpen=false;window.globiquest.dismissCelestial?.();scopeView.querySelectorAll('.interactive').forEach(el=>{el.setAttribute('data-feature-interactive','true');el.classList.remove('interactive')});constellations.querySelectorAll('.interactive').forEach(el=>{el.setAttribute('data-feature-interactive','true');el.classList.remove('interactive')})}}
